<template>
  <div class="box">
    <div class="leftBox">
      <div class="topBox">
        <div class="mouthBox">
          <i class="el-icon-arrow-left iconLeft" @click="timeChange('-')" />
          <div style="cursor: pointer">
            {{ time.yearNum }}年{{ time.monthNum }}月
          </div>
          <i class="el-icon-arrow-right iconRight" @click="timeChange('+')" />
        </div>
      </div>
      <div class="leftBox-bottomBox">
        <Calendar
          :time="time"
          :group-list="groupList"
          @cilckInfo="getClickInfo"
        />
      </div>
    </div>
    <div class="rightBox">
      <div
        class="topBox"
        style="justify-content: space-between; align-items: center"
      >
        <div v-if="infoData.year" class="clickTime">
          <span>
            {{
              `${infoData.year}年${infoData.month}月${
                infoData.item.date
              }&nbsp;&nbsp;&nbsp;周${weeks[infoData.index]}`
            }}
          </span>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
import Calendar from "@/components/GroupCalendar/index.vue";

export default {
  name: "Index",
  components: { Calendar },
  data() {
    return {
      isClickDay: false, // 是否选择日期
      groupList: [], // 排班数据
      time: {
        yearNum: "",
        monthNum: "",
      },
      infoData: {
        item: {},
      },
      weeks: ["日", "一", "二", "三", "四", "五", "六"],
      open: false,
    };
  },
  mounted() {
    this.getNow();

    this.groupList = require("./demoData.json").data;
    console.log(this.groupList, "groupList");
  },
  methods: {
    getClickInfo(e) {
      console.log(e, "选择了");
      this.infoData = e;
      this.isClickDay = true;
    },

    // 点击时间改变
    timeChange(e) {
      if (e === "+") {
        if (this.time.monthNum < 12) {
          this.time.monthNum++;
        } else if (this.time.monthNum === 12) {
          this.time.monthNum = 1;
          this.time.yearNum++;
        }
      } else {
        if (this.time.monthNum > 1) {
          this.time.monthNum--;
        } else if (this.time.monthNum === 1) {
          this.time.monthNum = 12;
          this.time.yearNum--;
        }
      }
    },

    // 获取当前年月
    getNow() {
      const timeOne = new Date();
      this.time.yearNum = timeOne.getFullYear();
      this.time.monthNum = timeOne.getMonth() + 1;
    },
  },
};
</script>

