<template>
  <div class="calendar">
    <table :class="isNormal === 1080 ? 'calendar-table' : 'calendar-table1366'">
      <thead>
        <tr>
          <th v-for="(item, i) in weeks" :key="i">
            <span :style="i === 0 || i === 6 ? 'color:#D40000;' : ''">{{
              item
            }}</span>
          </th>
        </tr>
      </thead>
      <tbody
        :class="[
          { tbodyBox: showDays.length > 35 && isNormal === 1080 },
          { tbodyBox1366: isNormal !== 1080 },
        ]"
      >
        <tr v-for="(dates, i) in res" :key="i">
          <td
            v-for="(item, index) in dates"
            :key="index"
            style="position: relative"
            :class="{
              notCurMonth: !item.isCurMonth,
              currentDay: item.date === curDate,
              selectDay: item.isSelected,
              rangeSelectd: item.isRangeSelected,
              weekend: item.isWeekend,
            }"
            @click="handleItemClick(item, i, index)"
          >
            <span
              v-if="index === 0 || index === 6"
              :class="isNormal === 1080 ? 'dayBox' : 'dayBox1366'"
              :style="
                item.isCurMonth ? 'color:#D40000;' : 'color:rgba(212,0,0,0.3);'
              "
            >
              <span
                v-if="item.month === 10 && item.date === '01日'"
                style="white-space: nowrap"
                ><span class="festivalBox">国庆节</span>{{ item.date }}</span
              >
              <span v-else-if="item.month === 5 && item.date === '01日'"
                ><span class="festivalBox">劳动节</span>{{ item.date }}</span
              >
              <span v-else-if="item.month === 1 && item.date === '01日'"
                ><span class="festivalBox">元旦</span>{{ item.date }}</span
              >
              <span v-else>{{ item.date }}</span>
            </span>
            <span v-else :class="isNormal === 1080 ? 'dayBox' : 'dayBox1366'">
              <span v-if="item.month === 10 && item.date === '01日'"
                ><span class="festivalBox" style="color: #f73131">国庆节</span
                >{{ item.date }}</span
              >
              <span v-else-if="item.month === 5 && item.date === '01日'"
                ><span class="festivalBox" style="color: #f73131">劳动节</span
                >{{ item.date }}</span
              >
              <span v-else-if="item.month === 1 && item.date === '01日'"
                ><span class="festivalBox" style="color: #f73131">元旦</span
                >{{ item.date }}</span
              >
              <span v-else>{{ item.date }}</span>
            </span>
            <div v-if="item.data">
              <div class="dutyBox">
                <div class="titleLeft">领导:</div>
                {{ item.data.dutyName }}
              </div>
              <div
                v-for="(person, index) in item.data.groupPersonList"
                :key="index"
                class="personBox"
              >
                <div v-if="index === 0" style="display: flex">
                  <div class="titleLeft">人员:</div>
                  {{ showName(person.personName) }}
                </div>
                <div
                  v-else-if="index < 2 && isNormal === 1080"
                  class="spaceBox"
                >
                  {{ person.personName }}
                </div>
                <div
                  v-else-if="index < 2 && isNormal !== 1080"
                  class="spaceBox"
                >
                  {{ person.personName }}
                </div>
              </div>
            </div>
          </td>
        </tr>
      </tbody>
    </table>
  </div>
</template>

<script>
import {
  getDaysInMonth,
  handleCrateDate,
  handleCreateDatePicker,
  parseTime,
  handleCrateDays,
} from "./index";
export default {
  components: {},
  props: {
    groupList: {
      type: Array,
      // eslint-disable-next-line vue/require-valid-default-prop
      default: [],
    },
    time: {
      type: Object,
      // eslint-disable-next-line vue/require-valid-default-prop
      default: {
        year: new Date().getFullYear(),
        month: new Date().getMonth() + 1,
      },
    },
    selectMode: {
      type: String,
      default: "click",
    },
    startOfWeek: {
      type: Number,
      default: 1,
    },
    canSelect: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      isNormal: "",
      clickDay: {
        // 点击的日期
        i: "",
        index: "",
        item: "",
      },
      groupDays: [], // 排班日期列表
      monthOptions: [],
      yearOptions: [],
      weeks: ["日", "一", "二", "三", "四", "五", "六"],
      curYear: new Date().getFullYear(), // 当前年
      curMonth: new Date().getMonth(), // 当前月
      days: 0, // 当前月总共天数
      curDate: parseTime(new Date().getTime()), // 当前日期 yyyy-MM-dd 格式，用来匹配是否是当前日期
      prevDays: [], // 非当前月的上一月展示的日期
      rearDays: [], // 非当前月的下一月展示的日期
      curDays: [], // 当前月的日期
      showDays: [], // 总共展示的42个日期
      res: [], // 二维数组
      selectedDates: [], // 选中的日期
      selectedMode: false, // true表示点击， false表示滑动
    };
  },
  computed: {},
  watch: {
    curMonth: {
      handler(val) {
        this.handleGetDays(this.curYear, val, this.startOfWeek);
      },
    },
    groupList: {
      handler(val) {
        this.groupDays = val;
        this.handleGetDays(this.curYear, this.curMonth, this.startOfWeek);
      },
      deep: true,
    },
    time: {
      handler(val) {
        this.curYear = val.yearNum;
        this.curMonth = val.monthNum - 1;
      },
      immediate: true,
      deep: true,
    },
    curYear: {
      handler(val) {
        this.handleGetDays(val, this.curMonth, this.startOfWeek);
      },
    },
  },
  created() {
    this.isNormal = window.screen.height;
    this.weeks.unshift(...this.weeks.splice(this.startOfWeek - 1));
    this.handleGetDays(this.curYear, this.curMonth, this.startOfWeek);
    this.selectedMode = this.selectMode === "click";
  },
  mounted() {
    this.monthOptions = handleCreateDatePicker().months;
    this.yearOptions = handleCreateDatePicker().years;
    if (localStorage.selectedDates)
      this.selectedDates = JSON.parse(localStorage.selectedDates);
  },
  methods: {
    showName(name) {
      if (this.isNormal !== 1080) {
        if (name.length > 5) {
          return name.substring(0, 3) + "...";
        } else {
          return name;
        }
      } else {
        if (name.length > 7) {
          return name.substring(0, 3) + "...";
        } else {
          return name;
        }
      }
    },
    handleGetDays(year, month, startOfWeek) {
      this.showDays = [];
      this.days = getDaysInMonth(year, month);
      let firstDayOfWeek = new Date(`${year}-${month + 1}-01`).getDay();

      // 处理周起始日
      const obj = {
        1: "一",
        2: "二",
        3: "三",
        4: "四",
        5: "五",
        6: "六",
        0: "日",
      };
      const firstDayInCN = obj[firstDayOfWeek];
      const index = this.weeks.indexOf(firstDayInCN);

      if (firstDayOfWeek === 0) {
        // 星期天为0 星期一为1 ，以此类推
        firstDayOfWeek = 7;
      }

      this.prevDays = handleCrateDate(year, month, 1, index + 1, "prev");
      this.rearDays = handleCrateDate(
        year,
        month,
        1,
        42 - this.days - index,
        "rear"
      );

      this.curDays = handleCrateDate(year, month, 1, this.days);
      this.showDays.unshift(...this.prevDays);
      this.showDays.push(...this.curDays);
      this.showDays.push(...this.rearDays);
      this.showDays.forEach((item) => {
        item.date = handleCrateDays(item.date);
      });
      // 最后一列都是下个月的就不显示
      if (this.showDays[this.showDays.length - 7].isCurMonth === false) {
        this.showDays = this.showDays.slice(0, this.showDays.length - 7);
      }
      this.showDays.forEach((item) => {
        this.groupDays.map((item1) => {
          var dayNum = item1.dayNum;
          if (dayNum < 10) {
            dayNum = "0" + dayNum;
          }
          if (item.date === dayNum + "日" && item.isCurMonth === true) {
            item.data = item1;
          }
        });
      });
      this.res = this.handleFormatDates(this.showDays);
    },
    handleFormatDates(arr, size = 7) {
      // 传入长度42的原数组，最终转换成二维数组
      const arr2 = [];
      for (let i = 0; i < size; i++) {
        const temp = arr.slice(i * size, i * size + size);
        arr2.push(temp);
      }
      // console.log(arr2)
      return arr2;
    },
    handleItemClick(item, i, index) {
      if (item.isCurMonth === true) {
        if (this.clickDay.i !== "") {
          this.res[this.clickDay.i][this.clickDay.index].isSelected = false;
        }
        this.clickDay = {
          i,
          index,
          item,
          year: this.curYear,
          month: this.curMonth + 1,
        };
        this.$emit("cilckInfo", this.clickDay);
        this.res[i][index].isSelected = true;
      }
    },
  },
};
</script>

